// @vitest-environment jsdom
/* global describe, it, expect -- vitest globals (globals: true); declared for `eslint .` */
/**
 * ManagedSiteModal characterization (see managedSiteModalHarness.tsx).
 *
 * managedSiteModal.golden.json was captured once from the unmodified ManagedSiteModal (before its JSX
 * sections were moved to components/managedSiteModal/) and is never regenerated by this test.
 * - Scenarios: full API data with WordPress connected, the same without a WordPress connection, every request
 *   failing (HTTP 500), and empty responses.
 * - Action sequences reach every tab, control and dialog: every initial action, then the controls each action
 *   reveals (three levels deep for the first scenario, two for the others).
 * - Each sequence is replayed from a fresh mount and must produce the same record: every fetch (method, URL,
 *   headers, credentials, body) in order, window.open / clipboard / confirm / alert and prop callbacks; the DOM
 *   after the action and 3 s later (exact HTML, by SHA-256; the HTML itself stored gzipped for diffs); focus;
 *   and the available controls.
 * Open / close / reopen is pinned as well.
 */
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { gunzipSync } from "node:zlib";
import { openCloseRecord, replay, type RunRecord, type ScenarioName } from "./managedSiteModalHarness";

const here = dirname(fileURLToPath(import.meta.url));
const routes = JSON.parse(readFileSync(join(here, "managedSiteModal.routes.json"), "utf8"));
const golden = JSON.parse(readFileSync(join(here, "managedSiteModal.golden.json"), "utf8")) as {
  scenarios: Record<ScenarioName, RunRecord[]>;
  openClose: unknown;
  blobs: Record<string, string>;
};
const html = (h: string) => (golden.blobs[h] ? gunzipSync(Buffer.from(golden.blobs[h], "base64")).toString("utf8") : "");
const firstDiff = (a: string, b: string) => { let i = 0; while (i < a.length && a[i] === b[i]) i++; return `at ${i}: golden …${a.slice(Math.max(0, i - 80), i + 120)}… actual …${b.slice(Math.max(0, i - 80), i + 120)}…`; };

describe("ManagedSiteModal: recorded interaction sequences", () => {
  for (const [scenario, runs] of Object.entries(golden.scenarios) as Array<[ScenarioName, RunRecord[]]>) {
    describe(scenario, () => {
      it.each(runs.map((r, i) => [i, r.steps.map((s) => `${s.kind} ${s.desc}`).join(" > ") || "(initial)", r] as const))("#%i %s", async (_i, _label, expected) => {
        const { rec, html: actualHtml, later } = await replay(scenario, routes, expected.steps);
        if (rec.dom !== expected.dom) throw new Error(`DOM after the last action differs ${firstDiff(html(expected.dom), actualHtml)}`);
        if (rec.domLater !== expected.domLater) throw new Error(`DOM 3s later differs ${firstDiff(html(expected.domLater), later)}`);
        expect(rec).toEqual(expected);
      }, 60_000);
    });
  }
});

describe("ManagedSiteModal: open / close / reopen", () => {
  it("renders nothing while closed and reloads on reopen as before", async () => {
    expect(await openCloseRecord(routes)).toEqual(golden.openClose);
  });
});
